SELECT 
    (SELECT count(*) FROM employees) AS employee_count,
    (SELECT count(*) FROM sales) AS sales_count;

SELECT e.name AS employee, COALESCE(m.name, 'Top Level Executive') AS manager
FROM employees e
LEFT JOIN employees m ON e.manager_id = m.emp_id;

SELECT dept, sum(salary) AS total_payroll 
FROM employees 
GROUP BY GROUPING SETS ((dept), ());

-- 04: Correlated Subquery (Employees earning above their department average)
SELECT e.name, e.dept, e.salary
FROM employees e
WHERE e.salary > (
    SELECT avg(sub.salary) FROM employees sub WHERE sub.dept = e.dept
);

SELECT e.emp_id, e.name 
FROM employees e 
WHERE EXISTS (
    SELECT 1 FROM sales s WHERE s.emp_id = e.emp_id
);

WITH RECURSIVE numbers AS (
    SELECT 1 AS n
    UNION ALL
    SELECT n + 1 FROM numbers WHERE n < 10
)
SELECT n FROM numbers;

SELECT sale_id, emp_id, amount, sale_date,
       SUM(amount) OVER (ORDER BY sale_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total
FROM sales;

SELECT emp_id FROM employees
EXCEPT
SELECT emp_id FROM sales;

INSERT INTO employees (emp_id, name, dept, salary, hired_at)
VALUES (1, 'Alice', 'Engineering', 130000.00, '2021-01-15')
ON CONFLICT (emp_id) DO NOTHING;

-- 15: Setting Transaction Isolation Level
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ;
SELECT sum(salary) FROM employees;
COMMIT;

BEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE READ ONLY;
SELECT count(*) FROM sales;
COMMIT;

SELECT sale_date, amount,
       AVG(amount) OVER (ORDER BY sale_date ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS rolling_7day_avg
FROM sales;

SELECT max(salary) AS second_highest_salary 
FROM employees 
WHERE salary < (SELECT max(salary) FROM employees);
